head.script:
scwin.trigger1_onclick = function(e) {
    trView.spanNode(1);
};
scwin.trigger2_onclick = function(e) {
    trView.spanNode(6);
};
scwin.trigger5_onclick = function(e) {
    trView.spanAll(true);
};
scwin.trigger6_onclick = function(e) {
    trView.spanAll(false);
};
scwin.trigger7_onclick = function(e) {
    trView.spanNode(1);
};
scwin.trigger8_onclick = function(e) {
    trView.spanNode(1, false);
};
scwin.trigger9_onclick = function(e) {
    trView.spanNode(1, true);
};
scwin.trigger10_onclick = function(e) {
    trView.spanNode(1, false, true);
};
scwin.trigger11_onclick = function(e) {
    trView.spanNode(1, true, true);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행하여 false를 클릭한다.
    //Run the sample file and click on false.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 하단 메뉴트리에서 menu1, menu2가 모두 접혀진다.
    //In the bottom menu tree, all of menu1 and menu2 are collapsed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_1').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_6').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. menu1 toggle 버튼을 2번 클릭한다.
    //Click the menu1 toggle button twice.
    //Verify 2. 하단 메뉴트리에서 menu1이 펼쳐지고 접혀진다.
    //In the bottom menu tree, menu1 is expanded and collapsed.
    //first click
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger7').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_1').style.display == 'block'", "true");
    //2nd click
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger7').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_1').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. menu1확장 버튼을 클릭한다.
    //Click the menu1 Extension button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger9').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 하단 메뉴트리에서 menu1이 펼쳐지고 메뉴1-2는 안펼쳐진다.
    //In the bottom menu tree, menu1 expands and menu 1-2 unfolds.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_1').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_3').style.display == 'none'", "true");
    //Test step4. menu1접기 버튼을 클릭한다.
    //Click the fold menu1 button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger8').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. 하단 메뉴트리에서 menu1이 접혀진다.
    //In the bottom menu tree, menu1 is collapsed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_1').style.display == 'none'", "true");
    //Test step 5. menu1자식포함확장 버튼을 클릭한다.
    // Click on the menu1 Include Child Extension button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger11').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify5. 하단 메뉴트리에서 menu1과 menu1-2가 펼쳐진다.
    //In the bottom menu tree, menu1 and menu1-2 are expanded.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_1').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_3').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_4').style.display == 'block'", "true");
    //Test step6. menu1자식포함접기 버튼을 클릭한다.
    //Click the fold menu1 Child Include button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger10').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 6. 하단 메뉴트리에서 menu1과 하위메뉴(menu1-2)가 접혀진다.
    //In the bottom menu tree, menu1 and its submenus (menu1-2) are collapsed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_1').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_3').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('trView_child_4').style.display == 'none'", "true");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create by Truong.Luu
    //Create date 22-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
